CREATE OR REPLACE PROCEDURE give_raise(p_emp NUMBER, p_pct NUMBER) IS
BEGIN
  IF p_pct > 20 THEN
    RAISE_APPLICATION_ERROR(-20001, 'Raise over 20% needs approval');
  END IF;
  UPDATE employees SET salary = salary * (1 + p_pct/100)
  WHERE employee_id = p_emp;
END;

CREATE OR REPLACE PACKAGE hr_api IS
  PROCEDURE give_raise(p_emp NUMBER, p_pct NUMBER);
  PROCEDURE transfer(p_emp NUMBER, p_dept NUMBER);
  FUNCTION annual_cost(p_emp NUMBER) RETURN NUMBER;
END hr_api;

CREATE OR REPLACE TRIGGER trg_emp_bi
BEFORE INSERT ON employees
FOR EACH ROW
BEGIN
  :NEW.email := LOWER(:NEW.email);
  IF :NEW.salary < 0 THEN
    RAISE_APPLICATION_ERROR(-20002, 'Salary must be positive');
  END IF;
END;

-- compound trigger skeleton: collect now, act once
CREATE OR REPLACE TRIGGER trg_emp_comp
FOR UPDATE OF salary ON employees COMPOUND TRIGGER
  TYPE t_ids IS TABLE OF NUMBER; v_ids t_ids := t_ids();
  AFTER EACH ROW IS BEGIN v_ids.EXTEND; v_ids(v_ids.LAST) := :NEW.employee_id; END AFTER EACH ROW;
  AFTER STATEMENT IS BEGIN /* bulk process v_ids */ END AFTER STATEMENT;
END;

